165: export class Character {
166:   constructor(scene, opts = {}) {
167:     this.scene = scene;
168:     this.model = makeCharacterModel(opts);
169:     this.group = this.model.group;
170:     this.group.position.set(opts.x ?? 0, 0.14, opts.z ?? 0);
171:     if (opts.heading !== undefined) this.group.rotation.y = opts.heading;
172:     this.heading = opts.heading ?? 0;
173:     this.health = opts.health ?? 100;
174:     this.maxHealth = this.health;
175:     this.alive = true;
176:     this.phase = Math.random() * 10;
177:     this.moveSpeed = 0;
178:     this.aiming = false;
179:     this.isPlayer = false;
180:     this.deadTime = 0;
181:     this.scale = opts.scale ?? 1;
182:     if (this.scale !== 1) this.group.scale.setScalar(this.scale);
183:     scene.add(this.group);
184:   }
185: 
186:   get pos() { return this.group.position; }
187: 
188:   setPosition(x, z) {
189:     this.group.position.x = x;
190:     this.group.position.z = z;
191:   }
192: 
193:   setHeading(h) {
194:     this.heading = h;
195:     this.group.rotation.y = h;
196:   }
197: 
198:   animate(dt, speed, aiming = false) {
199:     const model = this.model;
200:     this.phase += dt * (2.2 + speed * 1.5);
201:     const amt = clamp(speed / 6.5, 0, 1);
202:     if (!this.alive) {
203:       model.armL.rotation.x *= 0.9;
204:       model.armR.rotation.x *= 0.9;
205:       return;
206:     }
207:     if (speed > 0.12) {
208:       const s = Math.sin(this.phase);
209:       model.legL.rotation.x = s * 0.72 * amt;
210:       model.legR.rotation.x = -s * 0.72 * amt;
211:       model.armL.rotation.x = -s * 0.55 * amt;
212:       model.armR.rotation.x = s * 0.55 * amt;
213:       model.body.position.y = Math.abs(Math.sin(this.phase * 2)) * 0.035 * amt;
214:     } else {
215:       model.legL.rotation.x *= 0.85;
216:       model.legR.rotation.x *= 0.85;
217:       model.armL.rotation.x = Math.sin(this.phase * 0.4) * 0.03;
218:       model.armR.rotation.x = -Math.sin(this.phase * 0.4) * 0.03;
219:       model.body.position.y = Math.sin(this.phase * 0.6) * 0.008;
220:     }
221:     if (aiming) {
222:       model.armR.rotation.x = -1.42;
223:       model.armL.rotation.x = -1.2;
224:       model.armL.rotation.z = 0.32;
225:       model.armR.rotation.z = -0.08;
226:       model.aiming = true;
227:     } else {
228:       model.armL.rotation.z *= 0.8;
229:       model.armR.rotation.z *= 0.8;
230:     }
231:     this.aiming = aiming;
232:   }
233: 
234:   faceTowards(x, z, dt, speed = 12) {
235:     const target = Math.atan2(x - this.pos.x, z - this.pos.z);
236:     this.setHeading(lerpAngle(this.heading, target, clamp(dt * speed, 0, 1)));
237:   }
238: 
239:   damage(amount, game, opts = {}) {
240:     if (!this.alive) return false;
241:     this.health -= amount;
242:     if (this.health <= 0) {
243:       this.die(game, opts);
244:       return true;
245:     }
246:     return false;
247:   }
248: 
249:   die(game, opts = {}) {
250:     if (!this.alive) return;
251:     this.alive = false;
252:     this.deadTime = 0;
253:     this.moveSpeed = 0;
254:     this.model.setDeadPose(Math.random() < 0.5 ? 1 : -1);
255:     this.group.position.y = 0.16;
256:     const p = this.pos.clone();
257:     game.fx.blood(new THREE.Vector3(p.x, 1.1, p.z));
258:     game.fx.bloodPool(p);
259:     if (game.audio) game.audio.thud(p);
260:     if (opts.onDeath) opts.onDeath(this);
261:   }
262: 
263:   remove() {
264:     this.scene.remove(this.group);
265:   }
266: }
