272: const WEAPONS = [
273:   { id: 'pistol', name: 'PISTOL', icon: 'pistol', damage: 40, rate: 0.34, mag: 12, reserve: 96, spread: 0.012, range: 70, auto: false, pellets: 1 },
274:   { id: 'smg', name: 'MICRO SMG', icon: 'smg', damage: 17, rate: 0.085, mag: 30, reserve: 120, spread: 0.032, range: 55, auto: true, pellets: 1 },
275:   { id: 'shotgun', name: 'PUMP SHOTGUN', icon: 'shotgun', damage: 13, rate: 0.85, mag: 6, reserve: 36, spread: 0.075, range: 26, auto: false, pellets: 7 },
276: ];
277: 
278: export class Player extends Character {
279:   constructor(scene, game) {
280:     super(scene, {
281:       skin: 0xc98d64, shirt: 0xf0eee6, pants: 0x36455e, shoes: 0xe8e8e4,
282:       cap: true, capColor: 0x191a1d, armed: true, health: 100,
283:     });
284:     this.isPlayer = true;
285:     this.game = game;
286:     this.group.scale.setScalar(1.01);
287:     this.weapons = WEAPONS.map((w) => ({ ...w, ammo: w.mag, reserveAmmo: w.reserve }));
288:     this.weaponIndex = 0;
289:     this.aiming = false;
290:     this.sprinting = false;
291:     this.vehicle = null;
292:     this.armor = 0;
293:     this.vy = 0;
294:     this.jumping = false;
295:     this.stepTimer = 0;
296:     this.fireCooldown = 0;
297:     this.reloadTimer = 0;
298:     this.isDead = false;
299:     this._lastDamage = 0;
300:     this.model.setArmed(true);
301:   }
302: 
303:   get weapon() { return this.weapons[this.weaponIndex]; }
304:   get inVehicle() { return !!this.vehicle; }
305: 
306:   spawn(x, z, heading = 0) {
307:     this.group.position.set(x, 0.14, z);
308:     this.setHeading(heading);
309:     this.health = 100;
310:     this.armor = 0;
311:     this.alive = true;
312:     this.isDead = false;
313:     this.group.visible = true;
314:     this.model.body.rotation.z = 0;
315:     this.group.rotation.z = 0;
316:     this.vehicle = null;
317:     this.vy = 0;
318:     this.jumping = false;
319:     this.weaponIndex = 0;
320:     this.weapons.forEach((w) => { w.ammo = w.mag; w.reserveAmmo = w.reserve; });
321:     this.model.setArmed(true);
322:     if (this.game.hud) this.game.hud.setWeapon(this.weapon);
323:   }
324: 
325:   update(dt, input, game) {
326:     if (!this.alive) return;
327:     this.fireCooldown = Math.max(0, this.fireCooldown - dt);
328:     if (this.reloadTimer > 0) {
329:       this.reloadTimer -= dt;
330:       if (this.reloadTimer <= 0) this.finishReload(game);
331:     }
332: 
333:     if (this.vehicle) {
334:       this.group.position.copy(this.vehicle.group.position);
335:       this.group.position.y = 0.14;
336:       return;
337:     }
338: 
339:     this.aiming = input.aiming;
340:     const yaw = game.cameraYaw;
341:     const f = new THREE.Vector3(-Math.sin(yaw), 0, -Math.cos(yaw));
342:     const r = new THREE.Vector3(Math.cos(yaw), 0, -Math.sin(yaw));
343:     const dir = new THREE.Vector3();
344:     dir.addScaledVector(f, input.moveY);
345:     dir.addScaledVector(r, input.moveX);
346:     const len = dir.length();
347:     if (len > 1) dir.divideScalar(len);
348:     const moving = len > 0.08;
349: 
350:     this.sprinting = input.sprint && !this.aiming && moving;
351:     let speed = this.aiming ? 2.5 : this.sprinting ? 6.4 : 3.6;
352:     if (this.reloadTimer > 0) speed *= 0.75;
353:     this.moveSpeed = moving ? speed * Math.min(1, len) : 0;
354: 
355:     if (moving) {
356:       const target = Math.atan2(dir.x, dir.z);
357:       if (this.aiming) {
358:         this.setHeading(yaw + Math.PI);
359:       } else {
360:         this.setHeading(lerpAngle(this.heading, target, clamp(dt * 13, 0, 1)));
361:       }
362:       const vx = dir.x * this.moveSpeed;
363:       const vz = dir.z * this.moveSpeed;
364:       let nx = this.pos.x + vx * dt;
365:       let res = game.world.resolveCircle(nx, this.pos.z, 0.4);
366:       this.pos.x = res.x;
367:       this.pos.z = res.z;
368:       let nz = this.pos.z + vz * dt;
369:       res = game.world.resolveCircle(this.pos.x, nz, 0.4);
370:       this.pos.x = res.x;
371:       this.pos.z = res.z;
372: 
373:       // footsteps
374:       this.stepTimer -= dt * this.moveSpeed;
375:       if (this.stepTimer <= 0) {
376:         this.stepTimer = 2.4;
377:         if (game.audio) game.audio.footstep(this.sprinting);
378:       }
379:     }
380: 
381:     // jump
382:     if (input.jump && !this.jumping) {
383:       this.vy = 5.5;
384:       this.jumping = true;
385:       if (game.audio) game.audio.jump();
386:     }
387:     if (this.jumping) {
388:       this.vy -= 17 * dt;
389:       this.group.position.y += this.vy * dt;
390:       if (this.group.position.y <= 0.14) {
391:         this.group.position.y = 0.14;
392:         this.jumping = false;
393:         this.vy = 0;
394:       }
395:     }
396: 
397:     this.animate(dt, this.moveSpeed, this.aiming && this.reloadTimer <= 0);
398:     if (game.audio) game.audio.setFootstepsMoving(moving && !this.aiming, this.sprinting);
399: 
400:     // hit flash / health regen up to 45
401:     this._lastDamage += dt;
402:     if (this._lastDamage > 4 && this.health < 100) {
403:       this.health = Math.min(100, this.health + dt * 2.2);
404:     }
405:   }
406: 
407:   tryEnterVehicle(game, manual = true) {
408:     if (this.vehicle || !this.alive) return false;
409:     const v = game.vehicles.nearest(this.pos, 4.6);
410:     if (!v) {
411:       if (manual) game.hud.subtitle('근처에 탑승할 차량이 없습니다.', 1.6);
412:       return false;
413:     }
414:     if (v.dead) {
415:       if (manual) game.hud.subtitle('폐차된 차량에는 탑승할 수 없습니다.', 1.6);
416:       return false;
417:     }
418:     if (Math.abs(v.speed) > 5.5) {
419:       if (manual) game.hud.subtitle('차량이 너무 빠릅니다! 속도를 줄이세요.', 1.8);
420:       return false;
421:     }
422:     this.vehicle = v;
423:     this.group.visible = false;
424:     v.enter(this);
425:     game.cameraYaw = v.heading + Math.PI;
426:     game.cameraPitch = 0.17;
427:     if (v.isPolice) game.addWanted(1, '경찰차를 훔쳤습니다');
428:     if (game.audio) game.audio.startEngine();
429:     if (game.radio) game.radio.start(v);
430:     game.hud.subtitle(v.name + ' 탑승 · F 하차 · H 경적', 2.2);
431:     return true;
432:   }
433: 
434:   exitVehicle(game) {
435:     if (!this.vehicle) return;
436:     const v = this.vehicle;
437:     if (Math.abs(v.speed) > 7.5) {
438:       game.hud.subtitle('차량이 너무 빠릅니다!', 1.4);
439:       return;
440:     }
441:     const side = new THREE.Vector3(Math.cos(v.heading), 0, -Math.sin(v.heading));
442:     let x = v.pos.x - side.x * 1.7;
443:     let z = v.pos.z - side.z * 1.7;
444:     const r = game.world.resolveCircle(x, z, 0.45);
445:     x = r.x;
446:     z = r.z;
447:     this.group.position.set(x, 0.14, z);
448:     this.group.visible = true;
449:     this.setHeading(v.heading);
450:     v.exit();
451:     this.vehicle = null;
452:     if (game.audio) game.audio.stopEngine();
453:     if (game.radio) game.radio.stop();
454:     game.cameraYaw = this.heading + Math.PI;
455:   }
456: 
457:   switchWeapon(i, game) {
458:     if (i < 0 || i >= this.weapons.length || i === this.weaponIndex) return;
459:     this.weaponIndex = i;
460:     this.reloadTimer = 0;
461:     if (game.hud) game.hud.setWeapon(this.weapon);
462:     if (game.audio) game.audio.click();
463:     game.hud.subtitle(`${this.weapon.name} 장착`, 1.2);
464:   }
465: 
466:   reload(game) {
467:     const w = this.weapon;
468:     if (this.reloadTimer > 0 || w.ammo >= w.mag || w.reserveAmmo <= 0) return;
469:     this.reloadTimer = w.id === 'shotgun' ? 1.5 : w.id === 'smg' ? 1.2 : 1.0;
470:     if (game.audio) game.audio.reload();
471:   }
472: 
473:   finishReload(game) {
474:     const w = this.weapon;
475:     const need = w.mag - w.ammo;
476:     const take = Math.min(need, w.reserveAmmo);
477:     w.ammo += take;
478:     w.reserveAmmo -= take;
479:     if (game.hud) game.hud.setWeapon(w);
480:   }
481: 
482:   damage(amount, game, opts = {}) {
483:     if (!this.alive || this.isDead) return;
484:     this._lastDamage = 0;
485:     let dmg = amount;
486:     if (this.armor > 0) {
487:       const absorbed = Math.min(this.armor, dmg * 0.7);
488:       this.armor -= absorbed;
489:       dmg -= absorbed;
490:     }
491:     this.health -= dmg;
492:     game.hud.damageFlash();
493:     if (game.audio) game.audio.playerHit();
494:     if (this.health <= 0) {
495:       this.health = 0;
496:       this.die(game);
497:       game.onPlayerDeath();
498:     }
499:   }
500: 
501:   die(game) {
502:     if (this.isDead) return;
503:     this.isDead = true;
504:     this.alive = false;
505:     this.vehicle = null;
506:     this.group.visible = true;
507:     this.group.position.y = 0.16;
508:     this.model.setDeadPose(1);
509:   }
510: }
