516: export class Pedestrian extends Character {
517:   constructor(scene, world, opts = {}) {
518:     super(scene, {
519:       x: 0, z: 0, health: 70,
520:       shirt: pick(SHIRTS), pants: pick(PANTS), skin: pick(SKIN),
521:       cap: Math.random() < 0.18, armed: false,
522:       scale: rand(0.92, 1.06), noShadow: true,
523:       hair: pick([0x2a211b, 0x151515, 0x6b4a2f, 0xa5793f, 0x8d8d8d]),
524:     });
525:     this.world = world;
526:     this.block = opts.block ?? pick(world.blocks);
527:     this.t = rand(0, 1000);
528:     this.speed = rand(1.0, 1.5);
529:     this.baseSpeed = this.speed;
530:     this.dir = Math.random() < 0.5 ? 1 : -1;
531:     this.fleeTimer = 0;
532:     this.idleTimer = rand(2, 8);
533:     this.corpseTimer = 0;
534:     this.rumor = false;
535:     const loop = world.sidewalkLoop(this.block, this.t);
536:     this.group.position.set(loop.x, 0.14, loop.z);
537:     this.setHeading(Math.atan2(loop.dx * this.dir, loop.dz * this.dir));
538:   }
539: 
540:   startle(source, game, strength = 1) {
541:     if (!this.alive) return;
542:     this.fleeTimer = Math.max(this.fleeTimer, 3 + strength * 2);
543:     const dx = this.pos.x - source.x;
544:     const dz = this.pos.z - source.z;
545:     const loop = this.world.sidewalkLoop(this.block, this.t);
546:     const dot = loop.dx * dx + loop.dz * dz;
547:     this.dir = dot >= 0 ? 1 : -1;
548:     if (game.audio && Math.random() < 0.25) game.audio.pedScream(this.pos);
549:   }
550: 
551:   update(dt, game) {
552:     if (!this.alive) {
553:       this.corpseTimer += dt;
554:       if (this.corpseTimer > 30) {
555:         this.scene.remove(this.group);
556:         this.removed = true;
557:       }
558:       return;
559:     }
560:     this.fleeTimer = Math.max(0, this.fleeTimer - dt);
561:     const fleeing = this.fleeTimer > 0;
562:     let speed = fleeing ? 4.4 : this.speed;
563: 
564:     if (!fleeing) {
565:       this.idleTimer -= dt;
566:       if (this.idleTimer < 0) {
567:         this.idleTimer = rand(3, 9);
568:         this.idle = !this.idle;
569:       }
570:       if (this.idle) speed = 0;
571:     }
572: 
573:     // react to cars speeding nearby
574:     if (!fleeing && game.player.vehicle) {
575:       const d = this.pos.distanceTo(game.player.vehicle.pos);
576:       if (d < 11 && Math.abs(game.player.vehicle.speed) > 9) this.startle(game.player.vehicle.pos, game, 0.4);
577:     }
578: 
579:     this.moveSpeed = speed;
580:     if (speed > 0) {
581:       const loop = this.world.sidewalkLoop(this.block, this.t);
582:       this.t += this.dir * speed * dt;
