1339:     else if (p < 2 * w + d) { x = x1 - (p - w - d); z = z1; dx = -1; dz = 0; }
1340:     else { x = x0; z = z1 - (p - 2 * w - d); dx = 0; dz = -1; }
1341:     return { x, z, dx, dz, per };
