    const dz = this.pos.z - playerPos.z;
    if (Math.hypot(dx,dz) > 0.01) this.target = { x: this.pos.x + dx/Math.hypot(dx,dz)*12, z: this.pos.z + dz/Math.hypot(dx,dz)*12 };
  }
  this.fleeTimer = Math.max(0, this.fleeTimer - dt);
  if (this.fleeTimer > 0) {
    this.speed = 7.5;
  } else {
    this.idleTimer -= dt;
    if (this.idleTimer <= 0) { ... choose new target ...}
    this.speed = this.target ? 2.2 : 0;
  }
  if (this.target) {
    const dx = this.target.x - this.pos.x, dz = this.target.z - this.pos.z;
    const d = Math.hypot(dx,dz);
    if (d < 0.8) { this.target = null; this.speed = 0; this.idleTimer = rand(1.5,5); }
    else {
      const nx = this.pos.x + (dx/d)*this.speed*dt;
      const nz = this.pos.z + (dz/d)*this.speed*dt;
      const res = this.world.resolveCircle(nx, nz, 0.25);
      this.pos.x = res.x; this.pos.z = res.z;
      if (res.hit) { this.target = null; this.idleTimer = rand(0.5,2); }
      this.setHeading(lerpAngle(this.heading, Math.atan2(dx,dz), clamp(dt*8,0,1)));
    }
  }
  // stay near home
  const hd = Math.hypot(this.pos.x - this.home.x, this.pos.z - this.home.z);
  if (hd > 22) this.target = { ...this.home };
  // animate
