    if (!target) return;
    const tp = target.vehicle ? target.vehicle.pos : target.pos;
    if (!tp) return;
    tx = tp.x;
    tz = tp.z;
    dist = Math.hypot(tx - this.pos.x, tz - this.pos.z);
