  if (this.speed < desiredSpeed - 0.4) this.throttle = 0.8;
  else if (this.speed > desiredSpeed + 1.2) this.throttle = -0.3;
  else this.throttle = 0.05;
  this.brake = desiredSpeed === 0 && this.speed > 0.4 ? 1 : 0;
  if (this.brake) this.throttle = 0;
}

