.touch-hint {
  position: absolute; bottom: 210px; left: 50%; transform: translateX(-50%);
  font-size: 11px; letter-spacing: 1px; color: rgba(255, 255, 255, 0.55);
  background: rgba(0, 0, 0, 0.4); padding: 6px 12px; border-radius: 20px;
  z-index: 30; pointer-events: none; animation: hintFade 6s ease forwards;
}
@keyframes hintFade { 0%, 70% { opacity: 1; } 100% { opacity: 0; } }

/* In-car touch controls: bottom-center steering pad */
.car-controls {
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  bottom: calc(max(20px, env(safe-area-inset-bottom)) + 10px);
  display: flex;
  align-items: flex-end;
  gap: 12px;
  pointer-events: none;
  z-index: 5;
}
.car-controls-label {
  position: absolute;
  top: -18px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 3px;
  color: rgba(255, 255, 255, 0.55);
  text-shadow: 0 2px 4px #000;
  white-space: nowrap;
}
.car-controls .tbtn.steer {
  width: 76px;
  height: 76px;
  font-size: 24px;
  color: rgba(255, 255, 255, 0.92);
  border-color: rgba(255, 255, 255, 0.5);
  background: rgba(10, 12, 14, 0.55);
}
.car-controls .tbtn.swap {
  width: 44px;
  height: 44px;
  align-self: flex-end;
  font-size: 15px;
  color: rgba(255, 255, 255, 0.8);
}
.car-controls .tbtn.swap.on {
  background: rgba(244, 197, 66, 0.35);
  border-color: rgba(244, 197, 66, 0.8);
  color: #ffe9ad;
}

/* While driving, hide on-foot combat controls */
body.driving #btn-fire,
body.driving #btn-aim,
body.driving #btn-jump,
body.driving #btn-sprint,
body.driving #btn-reload { display: none; }

